{"artifact":{"path":"union-acceptance/cut-identity.test.mjs","text":"import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { PHASE2_RULESET_ID, scanTerritory } from "../src/scan-territory.mjs";
import { encodeRelationalValue } from "@emsenn/rmn-semantic-conformance/relational-value";
import { semanticId } from "@emsenn/rmn-semantic-conformance";

function computeCutId(entry) {
  const encoded = encodeRelationalValue({
    profile: "org.emsenn.phase2.territory-cut.v1",
    ruleset: PHASE2_RULESET_ID,
    settlement: entry.settlement,
    violationCount: entry.violationCount,
    rules: entry.rules,
    paths: entry.paths,
  });
  return semanticId(["ascribe", encoded.type, encoded.term]);
}

const MANIFEST_FORWARD = JSON.stringify({
  name: "cut-test",
  "x-agentic-metro-enterprise": { "node-id": "cut-test", "operation-catalog": { op: {} } },
});

const MANIFEST_REVERSED = JSON.stringify({
  "x-agentic-metro-enterprise": { "operation-catalog": { op: {} }, "node-id": "cut-test" },
  name: "cut-test",
});

function makeTerritory(root, manifest) {
  mkdirSync(join(root, "src"), { recursive: true });
  writeFileSync(join(root, "src", "work.mjs"), 'const log = "ops.jsonl";\n');
  writeFileSync(join(root, "package.json"), manifest);
}

test("canonical-cut-ni-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-id-"));
  try {
    makeTerritory(root, MANIFEST_FORWARD);
    const report = scanTerritory(root);
    assert.ok(report.cutFrontier.length > 0, "expected at least one cut frontier entry");
    const entry = report.cutFrontier[0];
    const expectedCutId = computeCutId(entry);
    assert.ok(
      expectedCutId.startsWith("ni:///sha-256;"),
      "independently derived identity must be an RFC 6920 SHA-256 ni URI"
    );
    assert.equal(entry.cutId, expectedCutId);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("key-order-independent-cut-identity", () => {
  const rootA = mkdtempSync(join(tmpdir(), "cut-order-a-"));
  const rootB = mkdtempSync(join(tmpdir(), "cut-order-b-"));
  try {
    makeTerritory(rootA, MANIFEST_FORWARD);
    makeTerritory(rootB, MANIFEST_REVERSED);
    const reportA = scanTerritory(rootA);
    const reportB = scanTerritory(rootB);
    assert.ok(reportA.cutFrontier.length > 0, "expected cut entry from territory A");
    assert.ok(reportB.cutFrontier.length > 0, "expected cut entry from territory B");
    const entryA = reportA.cutFrontier[0];
    const entryB = reportB.cutFrontier[0];
    const cutIdA = computeCutId(entryA);
    const cutIdB = computeCutId(entryB);
    assert.equal(
      cutIdA,
      cutIdB,
      "independently computed cutId must be equal across territories with reversed manifest JSON property order"
    );
    const encodedForward = encodeRelationalValue({
      profile: "org.emsenn.phase2.territory-cut.v1",
      ruleset: PHASE2_RULESET_ID,
      settlement: entryA.settlement,
      violationCount: entryA.violationCount,
      rules: entryA.rules,
      paths: entryA.paths,
    });
    const encodedReversed = encodeRelationalValue({
      paths: entryA.paths,
      rules: entryA.rules,
      violationCount: entryA.violationCount,
      settlement: entryA.settlement,
      ruleset: PHASE2_RULESET_ID,
      profile: "org.emsenn.phase2.territory-cut.v1",
    });
    assert.equal(
      semanticId(["ascribe", encodedForward.type, encodedForward.term]),
      semanticId(["ascribe", encodedReversed.type, encodedReversed.term]),
      "encodeRelationalValue must yield identical bytes regardless of JavaScript property insertion order"
    );
    assert.equal(entryA.cutId, cutIdA);
    assert.equal(entryB.cutId, cutIdB);
  } finally {
    rmSync(rootA, { recursive: true, force: true });
    rmSync(rootB, { recursive: true, force: true });
  }
});

test("repeatable-cut-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-repeat-"));
  try {
    makeTerritory(root, MANIFEST_FORWARD);
    const report1 = scanTerritory(root);
    const report2 = scanTerritory(root);
    assert.ok(report1.cutFrontier.length > 0, "expected at least one cut entry");
    assert.equal(
      report1.cutFrontier.length,
      report2.cutFrontier.length,
      "frontier length must be stable across scans"
    );
    for (let i = 0; i < report1.cutFrontier.length; i++) {
      const cutId1 = computeCutId(report1.cutFrontier[i]);
      const cutId2 = computeCutId(report2.cutFrontier[i]);
      assert.equal(
        cutId1,
        cutId2,
        `independently derived cutId for entry ${i} must be stable across scans`
      );
      assert.equal(report1.cutFrontier[i].cutId, cutId1);
    }
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("material-change-changes-cut-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-change-"));
  try {
    makeTerritory(root, MANIFEST_FORWARD);
    const reportBefore = scanTerritory(root);
    assert.ok(reportBefore.cutFrontier.length > 0, "expected cut entry before material change");
    const entryBefore = reportBefore.cutFrontier[0];
    const cutIdBefore = computeCutId(entryBefore);

    writeFileSync(join(root, "live.jsonl"), "{}\n");

    const reportAfter = scanTerritory(root);
    assert.ok(reportAfter.cutFrontier.length > 0, "expected cut entry after material change");
    const entryAfter =
      reportAfter.cutFrontier.find((e) => e.settlement === entryBefore.settlement) ??
      reportAfter.cutFrontier[0];
    const cutIdAfter = computeCutId(entryAfter);

    assert.notEqual(
      cutIdBefore,
      cutIdAfter,
      "adding a forbidden path must produce a different independently derived cut identity"
    );
    assert.equal(entryBefore.cutId, cutIdBefore);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
"},"rationale":"Each test independently derives the expected cutId via encodeRelationalValue and semanticId using the exact carrier shape specified in the constraints, then asserts entry.cutId equals that value. The pre-cutId assertions (ni URI prefix, property-order parity via both territory-level and object-level forward/reversed encoding, scan stability, and material-change divergence) all pass against the incumbent, so every test fails solely because the incumbent cutFrontier entries carry no cutId property. The key-order-independent test explicitly constructs the carrier in both forward and reversed property order and proves encodeRelationalValue is insensitive to insertion order before reaching the red-witness assertion."}

